import{_ as s,o as e,c as p,a2 as a}from"./chunks/framework.BXzK3EA4.js";const o="data:image/png;base64,",n="/assets/8d2aaf4e401fab27.B4LvStOQ.png",c="/assets/8b8427bf221f88f1.DvAqKOQf.png",i="/assets/b927e9da9455eeaf.C47GSEQl.png",l="/assets/3d30a652c6a768d4.DX-Yd36k.png",m="/assets/a1643d845f68fcd9.DPP-AIo8.png",r="/assets/5396eb4716e06788.DzmoYT3f.png",g="/assets/367a8f988f38a01e.ChMRY4um.png",d="/assets/906ad49458baf47a.CLh89Why.png",f="/assets/c9e19c9d3b0e005a.CBjQylIt.png",h="/assets/2cbeabacb3a6e938.BooBdEfK.png",A="/assets/94785e36d248d6db.C42yHSsh.png",y=JSON.parse('{"title":"CentOS 6 / 7修改语言及时区","description":"","frontmatter":{"title":"CentOS 6 / 7修改语言及时区"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/centos-6-7-change-language-timezone.md","filePath":"ops-knowledge-base/operating-system/linux/centos-6-7-change-language-timezone.md","lastUpdated":1788259091000}'),S={name:"ops-knowledge-base/operating-system/linux/centos-6-7-change-language-timezone.md"};function b(u,t,G,M,x,F){return e(),p("div",null,[...t[0]||(t[0]=[a('<p><strong>CentOS6</strong></p><p>默认系统语言英语改为简体中文：</p><p>1.查询当日所有语言包执行： locale -a</p><p><img src="'+o+'" alt=""></p><p>2 .修改其配置文件：vi /etc/sysconfig/i18n ，将第一行默认项注释掉，修改完成后:wq保存并退出，重新启动即可有效。</p><p><img src="'+n+'" alt=""></p><p>3.我们可以使用yum下载wget来测试一下，发现系统语言已经成功切换为简体中文。</p><p><img src="'+c+'" alt=""></p><p>修改时间：</p><p>1.显示时间段以及硬件时间： date -R; Date ; Time--显示</p><p><img src="'+i+'" alt=""></p><p>+0800是中国大陆的北京时间。如果写明了+0800 (东八区) ,那就是指中国标准时间(中国标准时间) 。</p><p>北京和上海处在同一时间段，只能保留一个。而作为时间段代表上海已经具备足够的装备代表能力，因此其维护者没有足够的动力做改变。</p><p>2.设置为上海时区：cp /usr/share/zoneinfo/Asia/Shanghai / etc /localtime</p><p><img src="'+l+'" alt=""></p><p>时间的信息存在于/usr/share/zoneinfo/下面，本机的时间信息存在于/etc/localtime</p><p>3.显示系统时间以及硬件时间： date;hwclock -r</p><p><img src="'+m+'" alt=""></p><p><strong>CentOS7.x</strong></p><p>默认系统语言英语改为简体中文：</p><p>1 .查看当前语言配置：locale</p><p><img src="'+r+'" alt=""></p><p>显示支持英文显示。</p><p>2 .在CentOS7中，设置系统语言有两种方式：</p><p>执行：yum groupinstall &quot;fonts&quot; -y 查看是否有zh_CN.utf8语言包，如果没有就需要下载安装字体（如果有就跳过这一步）</p><p>临时设置：</p><p>执行： LANG=“zh_CN.UTF-8”，此时我们再执行df -Th就可以明显看出系统语言已经更改为简体中文了</p><p><img src="'+g+'" alt=""></p><p>缺点：重启服务器之后会还原到默认的系统语言</p><p>永久设置：</p><p>执行： localectl set-locale LANG=zh_CN.UTF-8，重启服务器后生效：reboot。当服务器关机或是重启后再下一次开机时，系统语言环境简体中文依旧生效。</p><p><img src="'+d+'" alt=""></p><p>修改时区：</p><p>查看当前时区信息：timedatectl | grep“时区”</p><p><img src="'+f+'" alt=""></p><p>使用timedatectl命令，设置为中国大陆(东八区)时间：</p><p>timedatectl list-timezones |grep Shanghai #显示系统当前已经知道时区</p><p>timedatectl set-timezone Asia/Shanghai #设置时区</p><p>timedatectl status #查看系统时间</p><p><img src="'+h+'" alt=""></p><p>执行：hwclock -w (与hwclock --systohc作用相同，执行时需要root权限) ，同步BIOS硬件时间。</p><p><img src="'+A+'" alt=""></p>',42)])])}const E=s(S,[["render",b]]);export{y as __pageData,E as default};
